import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused operator: Average Pool -> Sigmoid -> Sum
fused_code = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ inline float sigmoidf(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__global__ void fused_pool_sigmoid_sum_kernel(
    const float* __restrict__ input,
    float* __restrict__ out,
    int N, int C, int H, int W, int poolSize
) {
    int oh = H / poolSize;
    int ow = W / poolSize;
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * oh * ow;

    if (index < total) {
        int n = index / (C * oh * ow);
        int r = index % (C * oh * ow);
        int c = r / (oh * ow);
        int r2 = r % (oh * ow);
        int p = r2 / ow;
        int q = r2 % ow;

        float local_sum = 0.0f;
        for (int i = 0; i < poolSize; i++) {
            for (int j = 0; j < poolSize; j++) {
                int row = p * poolSize + i;
                int col = q * poolSize + j;
                local_sum += input[((n * C + c) * H + row) * W + col];
            }
        }

        float avg = local_sum / (poolSize * poolSize);
        float val = sigmoidf(avg);
        atomicAdd(&out[n], val);
    }
}

torch::Tensor fused_pool_sigmoid_sum_cuda(torch::Tensor input, int poolSize) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);

    int oh = H / poolSize;
    int ow = W / poolSize;
    auto out = torch::zeros({N}, input.options());

    int total = N * C * oh * ow;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    fused_pool_sigmoid_sum_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W, poolSize
    );

    return out;
}
"""

fused_decl = "torch::Tensor fused_pool_sigmoid_sum_cuda(torch::Tensor input, int poolSize);"

fused_ops = load_inline(
    name="fused_pool_sigmoid_sum",
    cpp_sources=fused_decl,
    cuda_sources=fused_code,
    functions=["fused_pool_sigmoid_sum_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model with fused average pooling, sigmoid, and sum as a custom CUDA operator.
    """
    def __init__(self, in_channels, out_channels, kernel_size, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.pool_kernel_size = pool_kernel_size

    def forward(self, x):
        x = self.conv(x)
        return fused_ops.fused_pool_sigmoid_sum_cuda(x, self.pool_kernel_size)
